// Поисковый запрос hh.ru (CLAUDE.md §5): параметры страницы /search/vacancy.
// Слова, период, роли, формат, город и образование — из настроек (⚙️ → 🔎 Поиск, онбординг по резюме;
// n8n/shared/settings.js), остальное — здесь.
// Общий код scripts/build-workflows.mjs (W0 — запрос по умолчанию), W1 «Plan» (запросы сбора) и «Score job»
// (сообщение о сборе), W7 (⚙️ → 🔎 Поиск): строка «// @include n8n/shared/search.js» (после n8n/shared/settings.js;
// названия ролей — из n8n/shared/hh-roles.js, если он подключён раньше).

const SEARCH_URL = 'https://hh.ru/search/vacancy';

// Решения пользователя 07.10.2026: frontend — по всему тексту вакансии («JavaScript-разработчик», fullstack и
// AI-вакансии с фронтендом в описании в названии слова frontend не несут; синонимы фронтенд и front-end hh
// подставляет сам). Стек и AI — только в названии: по всему тексту они приносят чужой бэкенд («React будет плюсом»).
// Замер за сутки: было 16 вакансий (всё в названии), стало 39

// Слово с пробелом — в кавычках, иначе язык запросов hh разобьёт его на два
const searchTerm = (w) => (w.includes(' ') ? `"${w}"` : w);

function searchText(s) {
  const anywhere = s['search.anywhere'].map(searchTerm);
  const inName = s['search.in_name'].map(searchTerm);
  return [...anywhere, ...(inName.length ? [`NAME:(${inName.join(' OR ')})`] : [])].join(' OR ');
}

// Параметры одного запроса: формат работы и город — свои у «удалёнки» и у «офиса» (searchQueries)
function searchParams(s, formats = s['search.formats'], areaId = null) {
  return [
    ['text', searchText(s)],
    ...s['search.roles'].map((id) => ['professional_role', String(id)]),
    ...formats.map((f) => ['work_format', f]),
    ...(areaId ? [['area', String(areaId)]] : []),
    ...s['search.education'].map((e) => ['education', e]),
    // Только за последние дни (решение пользователя 07.10.2026: за сутки)
    ['search_period', String(s['search.period'])],
    ['order_by', 'publication_time'],
    ['items_on_page', '100'],
    ['enable_snippets', 'true'],
    // Как в выдаче на сайте; с одиночными значениями фильтров на результат не влияет
    ['ored_clusters', 'true'],
  ];
}

// Запросы сбора (13.10.2026): удалёнка — по всем регионам, офис и гибрид — в городе из профиля (search.area).
// hh не умеет «удалёнка везде ИЛИ офис в городе» одним запросом, поэтому запросов до двух. Офис без города не ищем:
// по всем регионам это тысячи вакансий. [{ label, params }]; пусто — поиск не настроен
const FORMAT_NAMES = { REMOTE: 'удалёнка', HYBRID: 'гибрид', ON_SITE: 'офис', FIELD_WORK: 'разъездная' };
function searchQueries(s) {
  const formats = s['search.formats'];
  const office = formats.filter((f) => f !== 'REMOTE');
  const queries = [];
  if (formats.includes('REMOTE')) queries.push({ label: 'удалёнка', params: searchParams(s, ['REMOTE']) });
  if (office.length && s['search.area']) {
    queries.push({
      label: `${office.map((f) => FORMAT_NAMES[f]).join(' и ')}, ${s['search.area'].name}`,
      params: searchParams(s, office, s['search.area'].id),
    });
  }
  return queries;
}

// Подписи параметров для сообщения о сборе и настроек, в порядке показа. Технические (items_on_page,
// enable_snippets, ored_clusters) не показываем; роли и город — отдельно (searchFilters)
const SEARCH_LABELS = {
  work_format: FORMAT_NAMES,
  education: {
    not_required_or_not_specified: 'образование не требуется',
    special_secondary: 'среднее профессиональное',
    higher: 'высшее',
  },
  search_period: { 1: 'за сутки', 3: 'за 3 дня', 7: 'за неделю' },
  order_by: { publication_time: 'сначала новые' },
};
// Название роли hh: справочник n8n/shared/hh-roles.js, если подключён
const roleName = (id) => (typeof HH_ROLES === 'undefined' ? `роль ${id}` : (HH_ROLES[id] ?? `роль ${id}`)).toLowerCase();

// Ссылка на ту же выдачу на hh (page — с нуля, как в запросе); params — запрос из searchQueries (по умолчанию первый)
const searchUrl = (page, s, params = searchQueries(s)[0]?.params ?? searchParams(s)) =>
  `${SEARCH_URL}?${[...params, ['page', String(page)]]
    .map(([key, value]) => `${key}=${encodeURIComponent(value)}`)
    .join('&')}`;

// Что искали, по-человечески: где какие слова и строка фильтров
function describeSearch(s) {
  const formats = s['search.formats'].map((f) => FORMAT_NAMES[f]);
  const filters = [
    `${formats.join(', ')}${s['search.area'] && s['search.formats'].some((f) => f !== 'REMOTE') ? ` (офис и гибрид — ${s['search.area'].name})` : ''}`,
    s['search.roles'].length ? s['search.roles'].map(roleName).join(', ') : 'все роли',
    s['search.education'].length ? `образование: ${s['search.education'].map((e) => SEARCH_LABELS.education[e] ?? e).join(' или ')}` : null,
    SEARCH_LABELS.search_period[s['search.period']] ?? `за ${s['search.period']} дн.`,
    SEARCH_LABELS.order_by.publication_time,
  ];
  const words = [
    s['search.anywhere'].length && `везде в тексте: ${s['search.anywhere'].join(' · ')}`,
    s['search.in_name'].length && `в названии: ${s['search.in_name'].join(' · ')}`,
  ];
  return { words: words.filter(Boolean).join('\n'), filters: filters.filter(Boolean).join(' · ') };
}

// Несколько резюме в приложении (16.10.2026, docs/resumes.md). Основное резюме r1 — глобальные ключи settings
// (profile.*, llm.*, search.*), у r2–r5 свои данные в resume.<id>. Потребители (W1, W2, W5) берут настройки
// резюме через resumeSettings() и дальше работают как раньше: у одного резюме результат — те же самые настройки.
// Общий код: строка «// @include n8n/shared/resumes.js» сразу после n8n/shared/settings.js.

const MAX_RESUMES = 5;
const RESUME_IDS = ['r1', 'r2', 'r3', 'r4', 'r5'];
// Резюме, по которым идёт поиск за один сбор: каждое — до двух запросов к hh (удалёнка, офис в городе)
const MAX_SEARCH_RESUMES = 3;

// Список резюме { id, name, active, hh }; s — результат loadSettings. Пока список не сохранён — одно основное:
// название из должности в профиле, привязка к hh — из разметки W13
function resumeList(s) {
  const list = Array.isArray(s.resumes) ? s.resumes : [];
  // Привязка основного резюме к hh: разметка W13 (cv) её создаёт и меняет (💼). Сохранённая в списке — то же резюме hh
  // с названием посвежее (импорт обновляет названия по списку hh), поэтому при том же хеше берём её; другой хеш — резюме
  // перепривязали в W13, берём cv
  const mainHh = s.cv?.resumes?.[0]?.hh ?? null;
  if (list.length) {
    return list.map((r) => (r.id === 'r1' ? { ...r, hh: r.hh && (!mainHh || r.hh.hash === mainHh.hash) ? r.hh : (mainHh ?? r.hh ?? null) } : r));
  }
  return [
    {
      id: 'r1',
      name: String(s['profile.facts']?.position || '').trim().slice(0, 60) || 'Основное',
      active: true,
      hh: mainHh,
    },
  ];
}

const resumeById = (s, id) => resumeList(s).find((r) => r.id === id) ?? null;

// Резюме, по которым идёт сбор
const activeResumes = (s) => resumeList(s).filter((r) => r.active);

// Свободный id для нового резюме (r2–r5) или null, если всё занято
function nextResumeId(s) {
  const used = new Set(resumeList(s).map((r) => r.id));
  return RESUME_IDS.find((id) => !used.has(id)) ?? null;
}

// Чего нет в resume.<id>, у r2–r5 нейтрально, а не как по умолчанию у ключа: умолчания ключей — настройки
// фронтенд-владельца (слова поиска, стоп-слова, спорные случаи), другой профессии они не подходят
const RESUME_NEUTRAL = {
  resume: '',
  extra: '',
  facts: {},
  about: [],
  preset: 'generic',
  rules: {},
  cases: [],
  roles: [],
  in_name: [],
  anywhere: [],
  formats: ['REMOTE'],
  area: null,
  education: ['not_required_or_not_specified'],
  stop_words: [],
  rules_off: ['lead'],
  examples: '',
  prompt: {},
};

// Есть ли у резюме слова для поиска: без них искать нечего (по роли одной — сотни чужих вакансий)
const resumeSearchable = (rs) => rs['search.anywhere'].length + rs['search.in_name'].length > 0;

// Данные резюме из настроек (то, что у r2–r5 лежит в resume.<id>): для клонирования и записи
function resumeData(s) {
  return Object.fromEntries(Object.entries(RESUME_FIELDS).map(([field, key]) => [field, s[key]]));
}

// Ключи settings с разметкой (cv) и версиями для отката (history) резюме id — их ведёт W13. У основного — прежние
// cv и resume.history, у r2–r5 — свои resume.<id>.cv и resume.<id>.history (не в resume.<id>: см. settings.js)
const resumeKeys = (id) =>
  !id || id === 'r1' ? { cv: 'cv', history: 'resume.history' } : { cv: `resume.${id}.cv`, history: `resume.${id}.history` };

// Настройки для резюме id: основное и неизвестное (удалённое, без данных) — сами s, остальные — копия s
// с подменёнными полями (чего нет в resume.<id> — нейтральное значение RESUME_NEUTRAL). Подменяются и cv, и
// resume.history (их читает W13). Копию не передавать в resumeList/resumeById/activeResumes: основное резюме берёт
// привязку к hh из cv, а в копии он чужой — список всегда по исходным настройкам
function resumeSettings(s, id) {
  if (!id || id === 'r1') return s;
  const data = s[`resume.${id}`];
  if (!data || !resumeById(s, id)) return s;
  const out = { ...s };
  for (const [field, key] of Object.entries(RESUME_FIELDS)) {
    out[key] = field in data ? data[field] : RESUME_NEUTRAL[field];
  }
  const keys = resumeKeys(id);
  out.cv = s[keys.cv] ?? null;
  out['resume.history'] = s[keys.history] ?? [];
  return out;
}

// Что записать в settings, чтобы поменять поля резюме id: { имя ключа: значение }.
// r1 — глобальные ключи, r2–r5 — один ключ resume.<id> с дописанными полями
function resumeRows(s, id, patch) {
  if (!id || id === 'r1') {
    return Object.fromEntries(Object.entries(patch).map(([field, value]) => [RESUME_FIELDS[field], value]));
  }
  return { [`resume.${id}`]: { ...(s[`resume.${id}`] ?? {}), ...patch } };
}

// Что записать в settings после правки резюме id в W13 (save — { 'profile.resume' | 'profile.extra' | cv |
// 'resume.history': значение }): основное — как есть, r2–r5 — текст и «Дополнительно» в resume.<id> (с прежними
// полями), разметка и версии — в свои ключи
function resumeSaveRows(s, id, save) {
  if (!id || id === 'r1') return save;
  const keys = resumeKeys(id);
  const out = {};
  const patch = {};
  for (const [key, value] of Object.entries(save)) {
    if (key === 'cv') out[keys.cv] = value;
    else if (key === 'resume.history') out[keys.history] = value;
    else {
      const field = Object.keys(RESUME_FIELDS).find((f) => RESUME_FIELDS[f] === key);
      if (field) patch[field] = value;
    }
  }
  return Object.keys(patch).length ? { ...out, ...resumeRows(s, id, patch) } : out;
}

// Вакансии резюме id: вакансию ведёт то резюме, которое её нашло; без резюме или с удалённым — основное.
// Одно резюме — все строки как есть. s — исходные настройки
function resumeVacancies(s, rows, id) {
  const list = resumeList(s);
  if (list.length < 2) return rows;
  const known = new Set(list.map((r) => r.id));
  return rows.filter((r) => (known.has(r.resume_id) ? r.resume_id : 'r1') === (id || 'r1'));
}

// Резюме, с которым работает W13 (рекомендации): target — выбор человека (static data), удалённое и без данных —
// основное. all — исходные настройки (loadSettings). → { id, name, s — настройки резюме, link — привязка к hh
// ({ hash, title } | null), several — резюме больше одного }
function resumeScope(all, target) {
  const id = target && target !== 'r1' && resumeById(all, target) && all[`resume.${target}`] ? target : 'r1';
  const r = resumeById(all, id);
  return { id, name: r?.name ?? '', s: resumeSettings(all, id), link: r?.hh ?? null, several: resumeList(all).length > 1 };
}

// Расписание сбора W1 по Москве (UTC+3, без перехода на летнее время). С 07.10.2026 задаётся в боте
// (⚙️ Настройки → 🕐 Сбор, n8n/shared/settings.js → scheduleFrom), сбор запускают «часы» W8 Clock.
// sch = { dayFrom, dayTo, dayEvery, nightEvery, paused }: днём [dayFrom, dayTo) — каждые dayEvery мин, ночью — каждые
// nightEvery мин (0 — ночью не собирать). Слоты выровнены по полуночи МСК, шаг сетки — 15 мин.
// По умолчанию (решение пользователя 07.10.2026) — 29 сборов в сутки: днём 07:00–17:30 каждые 30 мин,
// ночью 18, 20, 22, 00, 02, 04, 06.
// Общий код W1 «Score job», W6 «Summary», W7 «Render», W8 «Due»: строка «// @include n8n/shared/schedule.js».

const COLLECT_STEP = 15 * 60 * 1000;
const DEFAULT_SCHEDULE = { dayFrom: 7, dayTo: 18, dayEvery: 30, nightEvery: 120, paused: false };

// Момент t (мс, кратен 15 мин) — сбор по расписанию?
function isCollectSlot(t, sch = DEFAULT_SCHEDULE) {
  if (sch.paused) return false;
  const msk = new Date(t + 3 * 3600 * 1000);
  const hour = msk.getUTCHours();
  const every = hour >= sch.dayFrom && hour < sch.dayTo ? sch.dayEvery : sch.nightEvery;
  return every > 0 && (hour * 60 + msk.getUTCMinutes()) % every === 0;
}

// Сколько сборов по расписанию в промежутке (from, to]
function countCollectSlots(from, to, sch = DEFAULT_SCHEDULE) {
  let n = 0;
  for (let t = Math.floor(from / COLLECT_STEP) * COLLECT_STEP + COLLECT_STEP; t <= to; t += COLLECT_STEP) {
    if (isCollectSlot(t, sch)) n++;
  }
  return n;
}

// Ближайший сбор по расписанию после момента t; null — на паузе
function nextCollect(t, sch = DEFAULT_SCHEDULE) {
  if (sch.paused) return null;
  let s = Math.floor(t / COLLECT_STEP) * COLLECT_STEP + COLLECT_STEP;
  for (let i = 0; i < 2 * 96; i++, s += COLLECT_STEP) if (isCollectSlot(s, sch)) return s;
  return null;
}

// Сборов в сутки по расписанию
const collectsPerDay = (sch = DEFAULT_SCHEDULE) => countCollectSlots(0, 24 * 3600 * 1000, { ...sch, paused: false });

// Расписание словами: «днём 07–18 МСК каждые 30 мин, ночью каждые 2 ч»
function describeSchedule(sch = DEFAULT_SCHEDULE) {
  const every = (m) => (m % 60 ? `${m} мин` : `${m / 60} ч`);
  const pad = (n) => String(n).padStart(2, '0');
  const night = sch.nightEvery > 0 ? `ночью каждые ${every(sch.nightEvery)}` : 'ночью не собирать';
  return `днём ${pad(sch.dayFrom)}–${pad(sch.dayTo)} МСК каждые ${every(sch.dayEvery)}, ${night}`;
}

// Расписание стража healthchecks.io: OnCalendar (строка дня и строка ночи) и запас (grace, с)
function onCalendar(sch = DEFAULT_SCHEDULE) {
  const pad = (n) => String(n).padStart(2, '0');
  const minutes = [];
  for (let m = 0; m < 60; m += Math.min(sch.dayEvery, 60)) minutes.push(pad(m));
  const lines = [`${pad(sch.dayFrom)}..${pad(sch.dayTo - 1)}:${minutes.join(',')} Europe/Moscow`];
  if (sch.nightEvery > 0) {
    const hours = [];
    for (let h = 0; h < 24; h++) {
      if ((h < sch.dayFrom || h >= sch.dayTo) && (h * 60) % sch.nightEvery === 0) hours.push(pad(h));
    }
    if (hours.length) lines.push(`${hours.join(',')}:00 Europe/Moscow`);
  }
  return { schedule: lines.join('\n'), grace: (sch.dayEvery + 20) * 60 };
}

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const cut = (s, n) => (s.length > n ? `${s.slice(0, n - 1)}…` : s);
// Ноды ветки вакансий выполняются, только если в выдаче нашлись новые
const all = (name) => {
  try {
    return $(name)
      .all()
      .map((i) => i.json);
  } catch {
    return [];
  }
};
const count = (list, status) => list.filter((r) => r.status === status).length;
const plural = (n, one, few, many) => {
  const d = n % 10;
  const dd = n % 100;
  if (d === 1 && dd !== 11) return one;
  return d >= 2 && d <= 4 && (dd < 12 || dd > 14) ? few : many;
};
// Время: по местному, в скобках — по Москве, как в меню W7 (n8n/shared/time.js)

const plan = $('Plan').first().json;
const search = $('Parse search').first().json;
const requests = search.requests ?? [];
const fresh = all('Filter search'); // новые: new | rejected
// Страницы вакансий («Candidates»): строки этого сбора и хвост очереди new — после сбоя или разового догона
const freshIds = new Set(fresh.map((r) => r.external_id));
const opened = all('Parse vacancy'); // страница открыта: detailed | rejected
const parsed = opened.filter((r) => freshIds.has(r.external_id));
const queued = opened.filter((r) => !freshIds.has(r.external_id));
const rejected = [...fresh, ...parsed].filter((r) => r.status === 'rejected');
const scoring = parsed.filter((r) => r.status === 'detailed').length;
const noPage = opened.filter((r) => r.error).length;
// Очередь: строки new в таблице до открытия страниц минус открытые сейчас
const waiting = Math.max(0, all('Pending new').filter((r) => r.id).length - opened.length);

// Запросы к hh: страницы поиска + страницы вакансий
const sent = requests.length + opened.length;
let requestLine = `${sent} ${plural(sent, 'запрос', 'запроса', 'запросов')} к hh: поиск, ${requests
  .map((r) => `${requests.length > 1 && r.label ? `${r.label} ` : ''}стр. ${r.page + 1} → ${r.status}`)
  .join(', ')}`;
if (opened.length) {
  requestLine += ` · страницы вакансий: ${opened.length}`;
  if (noPage) requestLine += ` (не открылись ${noPage} — оценка по фрагменту)`;
}

const settings = loadSettings($('Settings').all());
const onPages = requests.reduce((n, r) => n + (r.count ?? 0), 0);
// Нашёл hh — по каждому запросу (удалёнка и офис в городе считаются отдельно); total на всех страницах запроса
// один и тот же — берём страницу 0
const totals = requests.filter((r) => r.total != null && r.page === 0);
const total = totals.length ? totals.reduce((n, r) => n + r.total, 0) : null;
// Период — из «Plan»: при догоне после простоя он шире настройки
const period = SEARCH_LABELS.search_period[plan.period ?? settings['search.period']];
const catchupLine = plan.catchup
  ? `⏩ Догоняю: успешного сбора не было ${plan.gapHours} ч — ищу ${period ?? `за ${plan.period} дн.`}, ${plan.pages} ${plural(plan.pages, 'страница', 'страницы', 'страниц')}`
  : '';
const queueLine =
  queued.length || waiting
    ? `📥 Из очереди: страниц ${queued.length} — на оценку ${count(queued, 'detailed')}, отсеяно ${count(queued, 'rejected')}${waiting ? ` · ждут ещё ${waiting}` : ''}`
    : '';
let result = 'все уже в базе';
if (fresh.length && !rejected.length) result = `новых ${fresh.length}, все на оценку`;
else if (fresh.length && !scoring) result = `новых ${fresh.length}, все отсеяны фильтром`;
else if (fresh.length) result = `новых ${fresh.length}: на оценку ${scoring}, отсеяно ${rejected.length}`;
const countLine = [
  total != null
    ? `hh нашёл${period ? ` ${period}` : ''} ${totals.length > 1 ? totals.map((r) => `${r.label} ${r.total}`).join(' + ') : total}`
    : '',
  total == null || onPages < total ? `на ${requests.length > 1 ? 'страницах' : 'странице'} ${onPages}` : '',
  `без дублей ${search.vacancies?.length ?? 0} — ${result}`,
]
  .filter(Boolean)
  .join(', ');

// Отсеянные: название — ссылка на hh, причины. «только из РФ: «цитата»» показываем с цитатой — видно ложные срабатывания
const SHOW = 5;
const rejectedLines = rejected
  .slice(0, SHOW)
  .map((r) => `🚫 <a href="${esc(r.url)}">${esc(r.title)}</a> — ${esc(cut(String(r.reasons ?? ''), 120))}`);
if (rejected.length > SHOW) rejectedLines.push(`и ещё ${rejected.length - SHOW}`);

// Что искали — по каждому резюме (при нескольких — с названием резюме)
const several = resumeList(settings).length > 1;
const searched = activeResumes(settings)
  .slice(0, MAX_SEARCH_RESUMES)
  .map((r) => ({ r, rs: resumeSettings(settings, r.id) }));
const searchedText = searched
  .map(({ r, rs }) => {
    const { words, filters } = describeSearch(rs);
    return `${several ? `📄 ${esc(r.name)}\n` : ''}${esc(words)}\n${esc(filters)}`;
  })
  .join('\n\n');
// Одинаковые адреса (как в «Plan») — одна ссылка, у первого резюме
const seenLinks = new Set();
const searchLinks = searched.flatMap(({ r, rs }) =>
  searchQueries(rs).flatMap((q, i, list) => {
    const url = searchUrl(0, rs, q.params);
    if (seenLinks.has(url)) return [];
    seenLinks.add(url);
    const what = list.length > 1 ? `поиск «${esc(q.label)}»` : 'этот поиск';
    return [`🔗 <a href="${esc(url)}">Открыть ${what}${several ? ` (${esc(r.name)})` : ''} на hh</a>`];
  }),
);
// Расписание — из настроек бота (⚙️ → 🕐 Сбор)
const next = nextCollect(Date.now(), scheduleFrom(settings));
const report = [
  `🔎 Сбор ${localMsk(plan.startedAt ?? Date.now())} · ${fresh.length ? `новых ${fresh.length}` : 'новых нет'}`,
  catchupLine,
  requestLine,
  countLine,
  ...rejectedLines,
  queueLine,
  `<blockquote expandable>${searchedText}</blockquote>`,
  ...searchLinks,
  next ? `Следующий сбор ${localMsk(next)}` : '⏸ Сбор на паузе — дальше только «🔄 Собрать сейчас» в ⚙️ Настройках',
]
  .filter(Boolean)
  .join('\n');

// Журнал сборов: запись из «Start run» и итог сбора. rejected, scoring, pages — всё, что сделал сбор, вместе с очередью
const run = {
  found: total ?? null,
  uniq: search.vacancies?.length ?? 0,
  fresh: fresh.length,
  rejected: rejected.length + count(queued, 'rejected'),
  scoring: scoring + count(queued, 'detailed'),
  pages: opened.length,
};

return [{ json: { report, runId: $('Start run').first().json.id, run } }];

// Recovered — открытые тревоги workflow → «✅ снова работает» (07.10.2026). Код одной ноды в W1 и W2:
// успешный запуск закрывает тревоги своего workflow («Close alerts»).
// Нода: Code, режим «Run Once for All Items». Вход: «Open alerts» — открытые тревоги этого workflow
// (Always Output Data: пустой item, если их нет). Выход: одно сообщение { text } или [] — закрывать нечего.

// Время человека (13.10.2026, docs/onboarding.md): часовой пояс — настройка profile.tz (IANA, например Asia/Bangkok),
// иначе пояс компьютера (USER_TZ из .env — его пишет мастер установки), иначе Москва. Расписание сбора по-прежнему
// считается по Москве (n8n/shared/schedule.js): hh публикует вакансии по МСК.
// Общий код: строка «// @include n8n/shared/time.js» — раньше n8n/shared/card.js и n8n/shared/robot.js (им нужен TZ).
// Пояс берётся из ноды «Settings», если она есть в workflow и уже выполнилась; без неё — USER_TZ.

const MSK_TZ = 'Europe/Moscow';
const validTz = (tz) => {
  try {
    return Boolean(tz) && Boolean(new Intl.DateTimeFormat('en-GB', { timeZone: tz }));
  } catch {
    return false;
  }
};

// Пояс этого запуска
function currentTz() {
  let tz = '';
  try {
    const row = $('Settings')
      .all()
      .map((i) => i.json)
      .find((r) => r?.name === 'profile.tz');
    tz = row ? JSON.parse(row.value_json) : '';
  } catch {
    // в workflow нет ноды «Settings» или строка битая — пояс компьютера
  }
  const env = typeof $env === 'undefined' ? '' : $env.USER_TZ;
  return [tz, env, MSK_TZ].find(validTz);
}
const TZ = currentTz();

// Части даты в поясе tz числами: { y, mo, d, h, mi }
function zonedParts(ms, tz = TZ) {
  const parts = new Intl.DateTimeFormat('en-GB', {
    timeZone: tz,
    hourCycle: 'h23',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
  }).formatToParts(new Date(ms));
  const get = (type) => Number(parts.find((p) => p.type === type).value);
  return { y: get('year'), mo: get('month'), d: get('day'), h: get('hour'), mi: get('minute') };
}
const pad2 = (n) => String(n).padStart(2, '0');

// 1760340720000 → '14:32'
const localHM = (ms, tz = TZ) => {
  const p = zonedParts(ms, tz);
  return `${pad2(p.h)}:${pad2(p.mi)}`;
};
// → '07.10'
const localDM = (ms, tz = TZ) => {
  const p = zonedParts(ms, tz);
  return `${pad2(p.d)}.${pad2(p.mo)}`;
};
// → '2026-10-07' — ключ дня
const localDay = (ms, tz = TZ) => {
  const p = zonedParts(ms, tz);
  return `${p.y}-${pad2(p.mo)}-${pad2(p.d)}`;
};
const localHour = (ms, tz = TZ) => zonedParts(ms, tz).h;

// Смещение пояса от UTC в минутах в момент ms (Бангкок: +420)
function tzOffsetMin(ms, tz = TZ) {
  const p = zonedParts(ms, tz);
  return Math.round((Date.UTC(p.y, p.mo - 1, p.d, p.h, p.mi) - Math.floor(ms / 60000) * 60000) / 60000);
}

// 'UTC+7', 'UTC+5:30', 'UTC−4'
function tzLabel(tz = TZ, ms = Date.now()) {
  const off = tzOffsetMin(ms, tz);
  const abs = Math.abs(off);
  return `UTC${off < 0 ? '−' : '+'}${Math.floor(abs / 60)}${abs % 60 ? `:${pad2(abs % 60)}` : ''}`;
}

// Начало «дня», который начинается в hour:00 по местному: последний такой момент не позже ms
function localDayStart(ms, tz = TZ, hour = 0) {
  const p = zonedParts(ms, tz);
  let start = Date.UTC(p.y, p.mo - 1, p.d, hour) - tzOffsetMin(ms, tz) * 60000;
  if (start > ms) start -= 24 * 3600 * 1000;
  return start;
}

// Тихие часы 23:00–09:00 по местному: карточки и сводка — без звука, тревоги — со звуком
const quietHours = (ms = Date.now(), tz = TZ) => {
  const h = localHour(ms, tz);
  return h >= 23 || h < 9;
};

// Время по местному и в скобках по Москве: '14:32 (10:32 МСК)'; пояс совпадает с Москвой — '10:32 МСК'
const localMsk = (ms, tz = TZ) =>
  tzOffsetMin(ms, tz) === tzOffsetMin(ms, MSK_TZ) ? `${localHM(ms, MSK_TZ)} МСК` : `${localHM(ms, tz)} (${localHM(ms, MSK_TZ)} МСК)`;

// Момент ISO (applied_at) → дата и время по местному: '2026-10-06T21:17:55Z' → '07.10', '04:17'
const localDate = (iso) => (Date.parse(iso) ? localDM(Date.parse(iso)) : '');
const localTime = (iso) => (Date.parse(iso) ? localHM(Date.parse(iso)) : '');

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const rows = $input
  .all()
  .map((i) => i.json)
  .filter((r) => r.id);
if (!rows.length) return [];

const hits = rows.reduce((n, r) => n + (Number(r.hits) || 1), 0);
const first = Math.min(...rows.map((r) => Date.parse(r.first_at) || Date.now()));
const last = Math.max(...rows.map((r) => Date.parse(r.last_at) || Date.now()));
const span = localHM(first) === localHM(last) ? localHM(first) : `${localHM(first)}–${localHM(last)}`;
return [{ json: { text: `✅ <b>${esc(rows[0].workflow)}</b> снова работает: ошибок было ${hits} (${span} по местному)` } }];
